mapper.select:
SELECT DATE_FORMAT(A.BOOK_DATE,'%Y-%m-%d') bookDate, A.BOOKSET_ID booksetId, bb.BOOKSET_NAME booksetName, A.VOUCH_NUM vouchNum, A.COM_TABLE_ID tableId, IFNULL(B.DETAIL_SUBJECT_NO,B.SUBJECT_NO) subjectNo, IFNULL(bbd.DETAIL_SUBJECT_NAME,bs.SUBJECT_NAME) subjectName, B.CD_FLAG cdFlag, B.ccy ccy, B.HAPPEN_AMT happenAmt, B.B_CCY bCcy, B.B_HAPPEN_AMT bHappenAmt, B.HAPPEN_NUMBER happenNumber, B.BUSI_ID busiId, IFNULL(fp.FINPROD_ABBR, stl.acct_name) busiName, B.TRADE_ID tradeId, fpd.P_TRADE_ID pTradeId, B.Book_Type bookType, A.OFFSET_FLAG offsetFlag, A.VOUCH_REMARK vouchRemark FROM (
select * from BOK_VOUCH_DETAIL where VOUCH_NUM in ( SELECT VOUCH_NUM FROM( SELECT b2.VOUCH_NUM , SUM( (case when b2.cd_flag = 'D' then 1 else -1 end)*B2.B_HAPPEN_AMT) FROM BOK_VOUCH_DETAIL B2 GROUP BY B2.VOUCH_NUM HAVING SUM( (case when b2.cd_flag = 'D' then 1 else -1 end)*B2.B_HAPPEN_AMT)!=0 ))) B JOIN bok_VOUCH_MAIN A ON A.VOUCH_NUM = B.VOUCH_NUM LEFT JOIN BOK_BOOKSET bb ON BB.BOOKSET_ID = A.BOOKSET_ID LEFT JOIN BOK_SUBJECT bs ON bs.BOOKSET_ID = bb.BOOKSET_ID_TMPL AND bs.SUBJECT_NO = B.SUBJECT_NO LEFT JOIN BOK_BUSS_DETSUB bbd ON bbd.BOOKSET_ID = A.BOOKSET_ID AND bbd.DETAIL_SUBJECT_NO = B.DETAIL_SUBJECT_NO LEFT JOIN trd_PRODUCT_DEAL fpd ON fpd.TRADE_ID = B.TRADE_ID lEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = B.BUSI_ID left join STL_CAPACCT_INFO stl on stl.acct_no = B.BUSI_ID WHERE 1=1
AND A.BOOKSET_ID IN
#{booksetId}
AND (
B.BUSI_ID like concat_ws('','%',#{busiId},'%') )
AND A.BOOK_DATE >= #{bookDateBegin}
AND A.BOOK_DATE <= #{bookDateEnd}
AND b.SUBJECT_NO not like '7%' ORDER BY A.BOOK_DATE DESC, A.BUS_VOUCHNUM DESC
